274:   /**
275:    * @typedef {Object} ReadRastersWindowOptions
276:    * @property {number} [resX] desired Y resolution (world units per pixel)
277:    * @property {number} [resY] desired X resolution (world units per pixel)
278:    * @property {Array<number>} [bbox] the subset to read data from in
279:    *     geographical coordinates. Whole image if not specified.
280:    */
281: 
282:   /**
283:    * (experimental) Reads raster data from the best fitting image. This function uses
284:    * the image with the lowest resolution that is still a higher resolution than the
285:    * requested resolution.
286:    * When specified, the `bbox` option is translated to the `window` option and the
287:    * `resX` and `resY` to `width` and `height` respectively.
288:    * Then, the [readRasters]{@link GeoTIFFImage#readRasters} method of the selected
289:    * image is called and the result returned.
290:    * @see GeoTIFFImage.readRasters
291:    * @param {ReadRastersOptions & ReadRastersWindowOptions} options optional parameters
292:    * @returns {Promise<ReadRasterResult>} the decoded array(s), with `height` and `width`, as a promise
293:    */
294:   async readRasters(options = {}) {
295:     const { window: imageWindow, width, height } = options;
296:     let { resX, resY, bbox } = options;
297: 
298:     const firstImage = await this.getImage();
299:     let usedImage = firstImage;
300:     const imageCount = await this.getImageCount();
301:     const imgBBox = firstImage.getBoundingBox();
302: 
303:     if (imageWindow && bbox) {
304:       throw new Error('Both "bbox" and "window" passed.');
305:     }
306: 
307:     // if width/height is passed, transform it to resolution
308:     if (width || height) {
309:       // if we have an image window (pixel coordinates), transform it to a BBox
310:       // using the origin/resolution of the first image.
311:       if (imageWindow) {
312:         const [oX, oY] = firstImage.getOrigin();
313:         const [rX, rY] = firstImage.getResolution();
314: 
315:         bbox = [
316:           oX + (imageWindow[0] * rX),
317:           oY + (imageWindow[1] * rY),
318:           oX + (imageWindow[2] * rX),
319:           oY + (imageWindow[3] * rY),
320:         ];
321:       }
322: 
323:       // if we have a bbox (or calculated one)
324: 
325:       const usedBBox = bbox || imgBBox;
326: 
327:       if (width) {
328:         if (resX) {
329:           throw new Error('Both width and resX passed');
330:         }
331:         resX = (usedBBox[2] - usedBBox[0]) / width;
332:       }
333:       if (height) {
334:         if (resY) {
335:           throw new Error('Both width and resY passed');
336:         }
337:         resY = (usedBBox[3] - usedBBox[1]) / height;
338:       }
339:     }
340: 
341:     // if resolution is set or calculated, try to get the image with the worst acceptable resolution
342:     if (resX || resY) {
343:       const allImages = [];
344:       for (let i = 0; i < imageCount; ++i) {
345:         const image = await this.getImage(i);
346:         const subfileType = image.fileDirectory.getValue('SubfileType');
347:         const newSubfileType = image.fileDirectory.getValue('NewSubfileType');
348:         if (i === 0 || subfileType === 2 || (newSubfileType || 0) & 1) {
349:           allImages.push(image);
350:         }
351:       }
352: 
353:       allImages.sort((a, b) => a.getWidth() - b.getWidth());
354:       for (let i = 0; i < allImages.length; ++i) {
355:         const image = allImages[i];
356:         const imgResX = (imgBBox[2] - imgBBox[0]) / image.getWidth();
357:         const imgResY = (imgBBox[3] - imgBBox[1]) / image.getHeight();
358: 
359:         usedImage = image;
360:         if ((resX && resX > imgResX) || (resY && resY > imgResY)) {
361:           break;
362:         }
363:       }
364:     }
365: 
366:     let wnd = imageWindow;
367:     if (bbox) {
368:       const [oX, oY] = firstImage.getOrigin();
369:       const [imageResX, imageResY] = usedImage.getResolution(firstImage);
370: 
371:       wnd = [
372:         Math.round((bbox[0] - oX) / imageResX),
373:         Math.round((bbox[1] - oY) / imageResY),
374:         Math.round((bbox[2] - oX) / imageResX),
375:         Math.round((bbox[3] - oY) / imageResY),
376:       ];
377:       wnd = [
378:         Math.min(wnd[0], wnd[2]),
379:         Math.min(wnd[1], wnd[3]),
380:         Math.max(wnd[0], wnd[2]),
381:         Math.max(wnd[1], wnd[3]),
382:       ];
383:     }
384: 
385:     return usedImage.readRasters({ ...options, window: wnd });
386:   }
