427:     const fallbackSize = this.bigTiff ? 4048 : 1024;
428:     return new DataSlice(
429:       (await this.source.fetch([{
430:         offset,
431:         length: typeof size !== 'undefined' ? size : fallbackSize,
432:       }]))[0],
433:       offset,
434:       this.littleEndian,
435:       this.bigTiff,
